//! Composing a `send` step's message (`PCAP2TEST_PIVOT_V3.md` §14 item 3).
//!
//! A send emits **exactly what `msg` states, plus tier-1 regeneration, plus any
//! run-config injected headers, plus any accessor substitution, plus the two
//! body rewrites: SDP's lane-owned lines and an MSCML response's echoed id
//! (RFC 5022 §10.2). Nothing else.**
//! This module owns the "plus" list and hands the stack a
//! [`MessageTemplate`](sip_template::MessageTemplate): tier-1 (Via and branch,
//! Call-ID, tags, CSeq numbering, Max-Forwards, Content-Length, Contact,
//! route sets) is regenerated by the stack and never stored here.
//!
//! No SIP is parsed in this crate: the frozen headers are already `{name,
//! value}` pairs — `sip-message` did the parsing at extraction — and this
//! module reassembles them.
//!
//! A tier-2 ref resolves through the lane's identity binding where it is
//! positional, and rides verbatim where the document froze it. A ref that
//! states its captured name-addr renders that, its `${num:…}` bound. A `${…}` is
//! substituted wherever it appears, including inside a frozen value: §8.1 states
//! there is no position where an accessor is literal text.

use std::collections::BTreeMap;
use std::path::Path;

use pivot_schema::body::Body;
use pivot_schema::bundle::RunConfig;
use pivot_schema::msg::{MsgSpec, Ref};
use sip_message::header::NameAddr;
use sip_message::{HeaderName, Method, MultipartPart, SipStr};
use sip_template::{MessageTemplate, TemplateHeader};

use crate::deviation::StepEffects;
use crate::media::{Booking, MediaMode};
use crate::mscml::{Echo, MscmlRequests};
use crate::resolve::{ResolveError, Resolver};

/// Why a step's message could not be composed.
#[derive(Debug, Clone, PartialEq, Eq)]
pub enum RenderError {
    /// A `${…}` in the message could not be resolved at emission time.
    Accessor { site: String, detail: String },
    /// A positional tier-2 ref naming a position the run cannot resolve to an
    /// identity.
    UnresolvedPosition { site: String, pos: String },
    /// The body resource could not be read.
    BodyUnreadable { reference: String, detail: String },
    /// A single-part body reference that declares neither SDP rewrite tags nor a
    /// content type: labelling it `application/sdp` would be a guess.
    BodyUnlabelled { reference: String },
    /// A multipart body that cannot be framed: the container names no multipart
    /// type, states no parts, or states a boundary a part's payload holds.
    MultipartUnframable { detail: String },
    /// A part a header references by `cid:` (§8.3 `cid-linked`) that states no
    /// `content-id` of its own: emitting it would leave the referencing header
    /// pointing at nothing (RFC 5621 §3).
    MultipartCidUnstated { reference: String, headers: Vec<String> },
    /// A `malformed-header` deviation naming a header the step does not carry:
    /// it would reproduce nothing.
    MalformedHeaderAbsent { site: String, header: String },
    /// A ref's `addr` that is no From/To identity: stated on a Request-URI,
    /// unreadable as a name-addr once resolved, or carrying the stack's tag.
    AddrRefused { site: String, addr: String, detail: String },
    /// The message states neither a method nor a status.
    NoStartLine,
}

impl std::fmt::Display for RenderError {
    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        match self {
            RenderError::Accessor { site, detail } => write!(f, "{site}: {detail}"),
            RenderError::UnresolvedPosition { site, pos } => {
                write!(f, "{site}: position {pos:?} resolves to no identity the lane bound")
            }
            RenderError::BodyUnreadable { reference, detail } => {
                write!(f, "body resource {reference:?}: {detail}")
            }
            RenderError::BodyUnlabelled { reference } => write!(
                f,
                "body resource {reference:?} declares neither SDP rewrite tags nor a content type"
            ),
            RenderError::MultipartUnframable { detail } => {
                write!(f, "the multipart body cannot be framed: {detail}")
            }
            RenderError::MultipartCidUnstated { reference, headers } => write!(
                f,
                "multipart part {reference:?} is referenced by cid: from {}, and the document \
                 states no content-id to emit it under",
                headers.join(", ")
            ),
            RenderError::MalformedHeaderAbsent { site, header } => write!(
                f,
                "{site}: a malformed-header deviation names {header:?}, which the step does not carry"
            ),
            RenderError::AddrRefused { site, addr, detail } => {
                write!(f, "{site}: name-addr {addr:?} refused: {detail}")
            }
            RenderError::NoStartLine => write!(f, "the message states neither a method nor a status"),
        }
    }
}

impl From<(&str, ResolveError)> for RenderError {
    fn from((site, error): (&str, ResolveError)) -> Self {
        RenderError::Accessor { site: site.to_string(), detail: error.to_string() }
    }
}

/// A composed message: the template the stack emits, plus the tier-2 URIs it
/// regenerates the dialog identity around.
#[derive(Debug, Clone, PartialEq)]
pub struct Rendered {
    pub template: MessageTemplate,
    pub ruri: Option<String>,
    pub from: Option<String>,
    pub to: Option<String>,
    /// The MSCML request types the message's responses answer, one entry per
    /// response: what the leg's record consumes once the message is composed.
    pub mscml_answered: Vec<String>,
}

/// How a lane turns a tier-2 position and a dial form into a URI. The
/// composition is the LANE's — a trunk-composed dialled form is a numbering-plan
/// fact, not a SIP one — so the interpreter asks rather than builds.
pub trait UriComposer {
    /// The URI for a positional ref. `is_ruri` selects the host: a Request-URI
    /// is addressed at the system under test, a From/To at the lane's domain.
    fn compose(&self, pos: &str, form: Option<&str>, is_ruri: bool) -> Option<String>;
    /// The URI for a value the document froze. `kind` is the ref's own class
    /// token: present means the frozen value is a whole ADDRESS (a URI minus
    /// its scheme), absent means a bare userpart the lane hosts.
    fn frozen(&self, value: &str, kind: Option<&str>, is_ruri: bool) -> String;
}

/// Everything composing a message needs beyond the message itself: the run's
/// own state, the lane's configuration and the deviations the step carries.
pub struct Context<'a> {
    pub resolver: &'a Resolver<'a>,
    pub config: &'a RunConfig,
    pub effects: &'a StepEffects,
    pub composer: &'a dyn UriComposer,
    /// Where a body resource reference resolves from.
    pub base_dir: &'a Path,
    /// The lane's media plane: what a rewritten SDP body's `c=` and `m=` lines
    /// carry.
    pub media: &'a Booking,
    /// The leg this send rides, which is what a media port is booked against.
    pub leg: &'a str,
    /// The MSCML requests that leg has received and not yet answered: the ids
    /// an MSCML response it sends echoes.
    pub mscml: &'a MscmlRequests,
    /// The lane directives for the CALL this step dials, where it dials one —
    /// empty on every other step. A call's egress is its own (§4.3).
    pub call_headers: &'a BTreeMap<String, String>,
}

/// Compose `msg` for the wire: exactly what it states, plus the additions
/// this module lists.
pub fn render(msg: &MsgSpec, site: &str, cx: &Context<'_>) -> Result<Rendered, RenderError> {
    let Context { resolver, config, effects, composer, base_dir, media, leg, mscml, call_headers } =
        *cx;
    let mut headers: Vec<TemplateHeader> = Vec::new();
    for header in &msg.headers {
        let name = resolver.text(&header.name).map_err(|e| RenderError::from((site, e)))?;
        let value = resolver.text(&header.value).map_err(|e| RenderError::from((site, e)))?;
        // A frozen header already rides EXACTLY as stored, so a deliberately
        // malformed one needs no special emission — but the deviation must find
        // the header it claims to break, or it silently reproduces nothing.
        headers.push(TemplateHeader::frozen(name, value));
    }
    for broken in &effects.malformed_headers {
        if !headers.iter().any(|h| h.name.eq_ignore_ascii_case(broken)) {
            return Err(RenderError::MalformedHeaderAbsent {
                site: site.to_string(),
                header: broken.clone(),
            });
        }
    }
    // Lane artifacts, stamped last so a document header of the same name wins:
    // an injected header is the lane's own, never part of the choreography.
    // This call's own directive goes on FIRST, so the more specific statement
    // wins over the run-wide one of the same name.
    for (name, value) in call_headers.iter().chain(&config.injected_headers) {
        if !headers.iter().any(|h| h.name.eq_ignore_ascii_case(name)) {
            headers.push(TemplateHeader::frozen(name.clone(), value.clone()));
        }
    }

    let mut echo = Echo::new(mscml);
    let (body, content_type) = match &msg.body {
        None => (Vec::new(), None),
        Some(body) => load_body(body, base_dir, media, leg, &mut echo)?,
    };
    if let Some(ct) = &content_type {
        if !headers.iter().any(|h| HeaderName::ContentType.matches(&h.name)) {
            headers.push(TemplateHeader::frozen("Content-Type", ct.clone()));
        }
    }

    let template = match (&msg.method, msg.status) {
        (Some(method), None) => MessageTemplate::request(Method::from_wire(method), headers, body),
        (None, Some(status)) => {
            MessageTemplate::response(status, msg.reason.clone().unwrap_or_default(), headers, body)
        }
        _ => return Err(RenderError::NoStartLine),
    };

    Ok(Rendered {
        template,
        ruri: uri(msg.ruri.as_ref(), site, "ruri", true, resolver, composer)?,
        from: uri(msg.from.as_ref(), site, "from", false, resolver, composer)?,
        to: uri(msg.to.as_ref(), site, "to", false, resolver, composer)?,
        mscml_answered: echo.answered(),
    })
}

/// One tier-2 ref, resolved: the name-addr it states, accessors substituted, or
/// else the URI the lane composes for it.
fn uri(
    r: Option<&Ref>,
    site: &str,
    what: &str,
    is_ruri: bool,
    resolver: &Resolver<'_>,
    composer: &dyn UriComposer,
) -> Result<Option<String>, RenderError> {
    let Some(r) = r else { return Ok(None) };
    let site = format!("{site} {what}");
    if let Some(addr) = r.addr() {
        let refused = |detail: String| RenderError::AddrRefused {
            site: site.clone(),
            addr: addr.to_string(),
            detail,
        };
        if is_ruri {
            return Err(refused("a Request-URI is an addr-spec the lane composes".into()));
        }
        let text = resolver.text(addr).map_err(|e| RenderError::from((site.as_str(), e)))?;
        return match NameAddr::parse(&SipStr::owned(&text)) {
            Err(error) => Err(refused(error.reason)),
            Ok(parsed) if parsed.params().has("tag") => {
                Err(refused("it carries a tag, which the stack mints".into()))
            }
            Ok(_) => Ok(Some(text)),
        };
    }
    match r {
        Ref::Positional(p) => {
            let pos = resolver.text(&p.pos).map_err(|e| RenderError::from((site.as_str(), e)))?;
            let form = match &p.form {
                None => None,
                Some(f) => {
                    Some(resolver.text(f).map_err(|e| RenderError::from((site.as_str(), e)))?)
                }
            };
            composer
                .compose(&pos, form.as_deref(), is_ruri)
                .map(Some)
                .ok_or(RenderError::UnresolvedPosition { site, pos })
        }
        Ref::Frozen(f) => {
            let value =
                resolver.text(&f.frozen).map_err(|e| RenderError::from((site.as_str(), e)))?;
            Ok(Some(composer.frozen(&value, f.kind.as_deref(), is_ruri)))
        }
    }
}

/// Which of §8.3's rewrite tokens a body states. Each token gates its OWN line
/// kind, so a document asking for one never gets the other.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
struct Rewrite {
    /// `c=addr`: every connection line takes the lane's media address.
    addr: bool,
    /// `m=port`: every active media line takes the port the lane booked it.
    port: bool,
}

impl Rewrite {
    fn of(tags: &[String]) -> Self {
        Rewrite {
            addr: tags.iter().any(|tag| tag == "c=addr"),
            port: tags.iter().any(|tag| tag == "m=port"),
        }
    }

    /// Whether the payload is rewritten at all — which is what declares it SDP.
    fn any(self) -> bool {
        self.addr || self.port
    }
}

/// Load a body resource and derive its content type. Two contents are
/// rewritten, direct or as a part: SDP (declared by its rewrite tags), only the
/// lines its tokens name and only where the lane's booking answers them — a
/// verbatim booking emits the stored bytes unchanged under the type the tags
/// declare, never decoding them; and an MSCML `<response>`, whose `id` takes
/// the one of the oldest request of its type `echo` has unanswered. Every other
/// payload, every part's `Content-ID` and every part entity header rides
/// exactly as stored (§8.3). A single reference declaring neither rewrite tags
/// nor a type is REFUSED rather than mislabelled.
fn load_body(
    body: &Body,
    base_dir: &Path,
    media: &Booking,
    leg: &str,
    echo: &mut Echo<'_>,
) -> Result<(Vec<u8>, Option<String>), RenderError> {
    match body {
        // A shape is an expect-side assertion, never a send body.
        Body::Shape(_) => Ok((Vec::new(), None)),
        // The parts are decomposed on disk and each rides byte-exact; the
        // FRAMING is regenerated, boundary included, because the document
        // stores the container type with its boundary stripped (§8.3).
        Body::Multipart(m) => {
            let mut parts: Vec<MultipartPart> = Vec::new();
            // One stream index runs across the whole BODY: two rewritten parts
            // describe two streams of one session, never two stream zeroes.
            let mut stream = 0usize;
            for part in &m.multipart.parts {
                if !part.cid_linked.is_empty() && part.content_id.is_none() {
                    return Err(RenderError::MultipartCidUnstated {
                        reference: part.reference.clone(),
                        headers: part.cid_linked.clone(),
                    });
                }
                let bytes = read(base_dir, &part.reference)?;
                let rewrite = Rewrite::of(&part.rewrite);
                let payload = if rewrite.any() {
                    let text = String::from_utf8_lossy(&bytes);
                    rewrite_sdp(&text, rewrite, media, leg, &mut stream).into_bytes()
                } else {
                    echo.body(bytes, &part.content_type)
                };
                // Content-Type is the composer's own first line; the stored
                // `Content-ID` leads the rest so a `cid:` reference resolves,
                // then the part's other entity headers in stored order.
                let mut composed = MultipartPart::new(part.content_type.clone(), payload);
                if let Some(content_id) = &part.content_id {
                    composed = composed.with_header("Content-ID", content_id.clone());
                }
                for header in &part.headers {
                    composed = composed.with_header(header.name.clone(), header.value.clone());
                }
                parts.push(composed);
            }
            let composed = sip_message::compose_multipart(&m.multipart.content_type, &parts)
                .map_err(|e| RenderError::MultipartUnframable { detail: e.to_string() })?;
            Ok((composed.body, Some(composed.content_type)))
        }
        Body::Resource(r) => {
            let bytes = read(base_dir, &r.reference)?;
            let rewrite = Rewrite::of(&r.rewrite);
            if !rewrite.any() {
                return match &r.content_type {
                    Some(ct) => Ok((echo.body(bytes, ct), Some(ct.clone()))),
                    None => Err(RenderError::BodyUnlabelled { reference: r.reference.clone() }),
                };
            }
            // Rewriting the payload never re-labels it: a stated type wins, so
            // an SDP body captured with parameters replays under them.
            let content_type =
                r.content_type.clone().unwrap_or_else(|| "application/sdp".to_string());
            // A verbatim booking answers no token: the stored bytes ride as
            // they are, invalid UTF-8 and every line ending included.
            if media.mode() == MediaMode::Verbatim {
                return Ok((bytes, Some(content_type)));
            }
            let text = String::from_utf8_lossy(&bytes).into_owned();
            let mut stream = 0usize;
            let payload = rewrite_sdp(&text, rewrite, media, leg, &mut stream).into_bytes();
            Ok((payload, Some(content_type)))
        }
    }
}

fn read(base_dir: &Path, reference: &str) -> Result<Vec<u8>, RenderError> {
    let path = base_dir.join(reference);
    std::fs::read(&path).map_err(|e| RenderError::BodyUnreadable {
        reference: reference.to_string(),
        detail: format!("{}: {e}", path.display()),
    })
}

/// Rewrite an SDP body's lane-owned fields — connection lines under `c=addr`,
/// media ports under `m=port` — keeping the framing byte-for-byte otherwise.
/// The line grammar is `sip_message::sdp`'s; this binds it to the lane's
/// booking: `stream` carries the body's active-media index across the body, so
/// the i-th active `m=` line takes the i-th port booked for `leg`, and a
/// rejected (port-0) stream consumes no index. A booking that answers no token
/// (a lane without media) leaves every line as stored.
fn rewrite_sdp(
    sdp: &str,
    rewrite: Rewrite,
    media: &Booking,
    leg: &str,
    stream: &mut usize,
) -> String {
    let addr = if rewrite.addr { media.addr() } else { None };
    sip_message::rewrite_connection_and_ports(sdp, addr, |pairs| {
        if !rewrite.port {
            return None;
        }
        let port = media.port(leg, *stream, pairs);
        *stream += 1;
        port
    })
}

